+import {createChatOrchestrator} from './chatOrchestrator.js';
+import type {OrchestratorHooks} from './chatOrchestrator.js';
+import {writeSignalPromptBuilder} from '../infrastructure/writeSignalTestSupport.js';
+import type {AIProvider, MessageChunk} from '../types/ai.js';
+import type {ChatSession} from '../types/session.js';
+
+const SENT_AT = '2026-01-01T00:00:00.000Z';
+
+const recordingProvider = (events: string[]): AIProvider => ({
+  async *sendMessage(): AsyncGenerator<MessageChunk> {
+    events.push('provider');
+    yield {type: 'stop', stopReason: 'end_turn'};
+  },
+  async generateStructured<T>(): Promise<T> {
+    return {} as T;
+  },
+});
+
+describe('ChatOrchestrator when beforeSession throws', () => {
+  it('calls onError then afterSession, skips the turn body, and rethrows the same error', async () => {
+    const events: string[] = [];
+    const failure = new Error('allocation failed');
+    const session: ChatSession = {
+      sessionId: 's1',
+      userId: 'u1',
+      entries: [{role: 'user', content: 'hello', timestamp: SENT_AT}],
+    };
+    const hooks: OrchestratorHooks = {
+      beforeSession: async () => {
+        events.push('beforeSession');
+        throw failure;
+      },
+      beforeUserInput: async (_s, message) => {
+        events.push('beforeUserInput');
+        return message;
+      },
+      afterUserInput: async () => void events.push('afterUserInput'),
+      beforeModelResponse: async (_s, prompt) => {
+        events.push('beforeModelResponse');
+        return prompt;
+      },
+      afterModelResponse: async () => void events.push('afterModelResponse'),
+      onError: async (failedSession, error) => {
+        events.push(`onError:${failedSession.sessionId}:${String(error === failure)}`);
+      },
+      afterSession: async endedSession => {
+        events.push(`afterSession:${endedSession.sessionId}`);
+      },
+    };
+    const orchestrator = createChatOrchestrator(recordingProvider(events), writeSignalPromptBuilder, undefined, {
+      hooks,
+    });
+
+    const outcome = await orchestrator.processMessage(session).then(
+      () => 'resolved',
+      (error: unknown) => (error === failure ? 'rethrew same error' : 'wrong error')
+    );
+
+    expect({outcome, events}).toEqual({
+      outcome: 'rethrew same error',
+      events: ['beforeSession', 'onError:s1:true', 'afterSession:s1'],
+    });
+  });
+});
